SELECT id, store_id, product_id, last_restock, LEAD(quantity, 1) OVER (PARTITION BY DATE_TRUNC('week', last_restock) ORDER BY quantity, id) next_quantity, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY YEAR(last_restock) ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_quantity, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY last_restock, id) row_seq, SUM(quantity) OVER (PARTITION BY product_id, store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_quantity, SUM(quantity) OVER w_ordered store_id_sum_quantity FROM inventory WINDOW w_ordered AS (PARTITION BY store_id);
